#define PI 3.141592
#define PHI 1.618033988749895
#define TAU (2.*PI)
#define SIN(x) (sin(x)*.5+.5)
#define COS(x) (cos(x)*.5+.5)
#define BUMP_EPS 0.004
#define sabsk(x, k) sqrt(x * x + k * k)
#define sabs(x) (sabsk(x, .1))
#define S(a, b, x) smoothstep(a, b, x)
#define SQR2 1.4152135
#define ISQR2 1./SQR2


float tt, g_mat;
vec3 ro;

mat2 rot(float a) { return mat2(cos(a), -sin(a), sin(a), cos(a)); }


float saturate(float x) {
    return clamp(x, 0., 1.);
}


// zucconis spectral palette https://www.alanzucconi.com/2017/07/15/improving-the-rainbow-2/
vec3 bump3y (vec3 x, vec3 yoffset)
{
    vec3 y = 1. - x * x;
    y = clamp((y-yoffset), vec3(0), vec3(1));
    return y;
}

//  some 2d noise for dithering
highp float random(highp vec2 coords) {
   return fract(sin(dot(coords.xy, vec2(12.9898,78.233))) * 43758.5453);
}


float rect( vec2 p, vec2 b, float r ) {
    vec2 d = abs(p) - (b - r);
    return length(max(d, 0.)) + min(max(d.x, d.y), 0.) - r;
}


vec3 invGamma(vec3 col) {
    return pow(col, vec3(2.2));
}

vec3 gamma(vec3 col) {
    return pow(col, vec3(1./2.2));
}

// Zucconi's spectral palette
vec3 spectral_zucconi6(float x) {
    x = fract(x);
    const vec3 c1 = vec3(3.54585104, 2.93225262, 2.41593945);
    const vec3 x1 = vec3(0.69549072, 0.49228336, 0.27699880);
    const vec3 y1 = vec3(0.02312639, 0.15225084, 0.52607955);
    const vec3 c2 = vec3(3.90307140, 3.21182957, 3.96587128);
    const vec3 x2 = vec3(0.11748627, 0.86755042, 0.66077860);
    const vec3 y2 = vec3(0.84897130, 0.88445281, 0.73949448);
    return bump3y(c1 * (x - x1), y1) + bump3y(c2 * (x - x2), y2) ;
}


// from https://mercury.sexy/hg_sdf/
float pModPolar(inout vec2 p, float repetitions) {
	float angle = 2.*PI/repetitions;
	float a = atan(p.y, p.x) + angle/2.;
	float r = length(p);
	float c = floor(a/angle);
	a = mod(a,angle) - angle/2.;
	p = vec2(cos(a), sin(a))*r;
	// For an odd number of repetitions, fix cell index of the cell in -x direction
	// (cell index would be e.g. -5 and 5 in the two halves of the cell):
	if (abs(c) >= (repetitions/2.)) c = abs(c);
	return c;
}



float box(vec3 p, vec3 r) {
  vec3 d = abs(p) - r;
  return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}



float smin(float a, float b, float k) {
  float h = clamp((a-b)/k * .5 + .5, 0.0, 1.0);
  return mix(a, b, h) - h*(1.-h)*k;
}



float pMod(float p, float size) {
	float halfsize = size*0.5;
	float c = floor((p + halfsize)/size);
	p = mod(p + halfsize, size) - halfsize;
	return p;
}

vec2 pMod(inout vec2 p, vec2 size) {
	vec2 halfsize = size*0.5;
	vec2 c = floor((p + halfsize)/size);
	p = mod(p + halfsize, size) - halfsize;
	return c;
}

float n21(vec2 p) {
      return fract(sin(dot(p, vec2(524.423,123.34)))*3228324.345);
}

float n21_(vec2 p) {
      return fract(dot(p, vec2(524.423,123.34))*3228324.345);
}

// smooth noise
float noise(vec2 n) {
    const vec2 d = vec2(0., 1.0);
    vec2 b = floor(n);
    vec2 f = mix(vec2(0.0), vec2(1.0), fract(n));
    return mix(mix(n21(b), n21(b + d.yx), f.x), mix(n21(b + d.xy), n21(b + d.yy), f.x), f.y);
}

float g_glow;


// Repeat only a few times: from indices <start> to <stop> (similar to above, but more flexible)
float pModInterval1(inout float p, float size, float start, float stop) {
	float halfsize = size*0.5;
	float c = floor((p + halfsize)/size);
	p = mod(p+halfsize, size) - halfsize;
	if (c > stop) { //yes, this might not be the best thing numerically.
		p += size*(c - stop);
		c = stop;
	}
	if (c <start) {
		p += size*(c - start);
		c = start;
	}
	return c;
}

vec3 g_p;

// by Nusan
float curve(float t, float d) {
  t/=d;
  return mix(floor(t), floor(t)+1., pow(smoothstep(0.,1.,fract(t)), 10.));
}
float opSub(float d1, float d2) {
	return max(-d1, d2);
}

float smax( float a, float b, float k )
{
    float h = max(k-abs(a-b),0.0);
    return max(a, b) + h*h*0.25/k;
}

float tetrahedron(vec3 p, float r) {

    // basically cutting a cube at the diagonal and scaling/centering it.
    p.yz *= rot(PI/2.);

    p.z -= ISQR2*r;
    vec3 bp = p;
    p.z *=  0.5;
    p.z -= ISQR2*r;

    p.yz *= rot(atan(ISQR2)*PI*.5);
    p.xy *= rot(PI/4.);

    return smax(box(p, vec3(r))-.05, bp.z, .05)*1.2;
}


void cam(inout vec3 p) {

  p.xz += vec2(-10.*sin(.2*tt), -10.*cos(.2*tt));
}

float tick(float t, float d) {
	float g = t/d;
    float it = fract(g);

    it = smoothstep(0., 1., it);
    it = smoothstep(0., 1., it);
    it = smoothstep(0., 1., it);


    return floor(g)+it;
}



float n31(vec3 p) {return fract(sin(dot(p, vec3(.3,.32,.343)))*.1);}
float n11(float h) {return fract(sin(h) * 102.53123);}

float noise31(vec3 x) {
	vec3 p = floor(x);
	vec3 f = fract(x);
	f = f * f * (3.0 - 2.0 * f);

	float n = p.x + p.y * 51.235212 + .242 * p.z;
	return mix(
			mix(mix(n11(n + 0.095874), n11(n + .2), f.x),
					mix(n11(n), n11(n ), f.x), f.y),
			mix(mix(n11(n + .052), n11(n), f.x),
					mix(n11(n ), n11(n), f.x), f.y), f.z);
}
float smoothNoise21(vec2 p) {
    // Calculate integer and fractional coordinates
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Compute gradients at the four corners of the cell
    float n00 = dot(vec2(cos(dot(i, vec2(127.1, 311.7))), sin(dot(i, vec2(127.1, 311.7)))), f - vec2(0.0, 0.0));
    float n01 = dot(vec2(cos(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7))), sin(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7)))), f - vec2(0.0, 1.0));
    float n10 = dot(vec2(cos(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7))), sin(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7)))), f - vec2(1.0, 0.0));
    float n11 = dot(vec2(cos(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7))), sin(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7)))), f - vec2(1.0, 1.0));

    // Smooth interpolation using Hermite curve (smoothstep)
    vec2 u = f * f * (3.0 - 2.0 * f);

    // Bilinear interpolation with gradients
    return mix(mix(n00, n10, u.x), mix(n01, n11, u.x), u.y);
}

float g_h;
float map(vec3 p) {   

     g_p = p;
    g_mat = 0.;
    float d = 1e9;

    vec3 bp = p;

    float m = PI*tick(tt, 2.)/8.;
    p.xz = abs(p.xz) - vec2(.9, 1.3);
     for(float i=0.; i < 2.; i++) {
        p.xz = abs(p.xz) - vec2(1, 2.)*.4;

        p.xz *= rot(PI/4.+.5*m);

    }

    float w = .6;
    d = box(p, vec3(w, 2, w));

    p = bp;

    p.y = pMod(p.y, 1.);

    d = max(d, -(abs(p.y)-.06));
    p = bp;

    p.y -= 1.9;

    p.xz = abs(p.xz) - 1.9;

    p.xy *= rot(PI/5.);
    p.yz *= rot(-PI/5.);
    d = max(d, p.y);

    p = bp;
  //  p.xz = abs(p.xz) + vec2(1.2, 2.)*.5;
    p.y-= .2;
     for(float i=0.; i < 2.; i++) {
        p = abs(p) - vec3(1.0, 1.4, 1.)*.5;
        p.xz *= rot(PI/6.-m);

    }
        p.xz = abs(p.xz) - vec2(1.2, 1.);

    float c = box(p, vec3(.6, .5, .6)*.9);

    d = max(d, -c);

    c = tetrahedron(p, 1.2);


    p =bp;
    p.xz = abs(p.xz) - 1.9;

    p.xz *= rot(PI/5.);
    p.xy *= rot(PI/5.);
    p.yz *= rot(-PI/5.);
    c = max(c, (p.y-1.9));
    d = min(c, d);

    p = bp;

    p.y += 1.;

    p.xz = abs(p.xz) - 1.9;

    p.xy *= rot(-PI/5.);
    p.yz *= rot(PI/5.);
    d = max(d, -p.y);

    p = bp;
    p.y += 1.;
    p.xz = abs(p.xz) - vec2(.9, 1.3)*1.4;
    w = .5;

    d = min(d, box(p, vec3(w, 3, w))-0.02);


    vec3 blocks = floor(p*1.4);
    blocks = vec3( SIN(blocks.y+3.*tt+252.*abs(n31(blocks))) );

   // float glitch = mix(.0, .04, S(0.5, 1., SIN(tt)));
   // glitch = mix(glitch, .4, S(0.9, 1., SIN(.5*tt)));

    float glitchS = bp.y+5.*sin(tt-PI);
    float glitch  = mix(0., .05, S(0., .2, glitchS));
    glitch -= .1*S(.1, .05, abs(glitchS) -0.03);


    d += dot(blocks, vec3(glitch));
    p = bp;
    float r = smoothNoise21(p.xz*.5-3.)*2.;
   // g_h = r;
    p.y += 3.1;
   // p.y = smin(smax(r*3.+sin(r), p.y, .3)-sin(r*2.), p.y+.1, .4);
    float h = p.y;
    //h = smax(p.y+r*.2 - .2*(abs(sin(r*2.))-.2), h, .01)-.3*(abs(sin(r*r*6.))-.2);
    p.y += r*.4;
    float fl  = smax(p.y, h-.1, 0.01)+.2*(abs(sin(r*r*2.))-.2);
    float water = h+.05;

    water = smax(-fl, water, 0.02);
    g_mat = water < -fl ? 2. : g_mat;
    fl = smin(water, fl, .01);

    g_mat = fl < d ? 1. : g_mat;

    d = min(d, fl);
    g_mat = water == d ? 2. : g_mat;

    return d*.5;
}


vec3 getNormal(vec3 p) {

    vec2 eps = vec2(0.001, 0.0);
    return normalize(vec3(map(p + eps.xyy) - map(p - eps.xyy),
                          map(p + eps.yxy) - map(p - eps.yxy),
                          map(p + eps.yyx) - map(p - eps.yyx)
                         )
                     );
}

float stars(vec2 p) {

    float N = 20.;
    vec2 id = floor(p*N)-.5;
    p = fract(p*N)-.5;

    float s = noise(id*20.+ 4.);
    float v = float(noise(id*30.+6.) < .004);


    p.xy += vec2(noise(id*30.+ 1.), noise(id*20.+ 3.))*.3-.4;

    return 2.*(1.-pow(smoothstep(.0, .1*s, (length(p))), 3.))*v;
}

// iq's shadow function
float softshadow( in vec3 ro, in vec3 rd, float mint, float maxt, float k ) {

    float res = 1.0;
    float ph = 1e20;
    for( float t=mint; t<maxt; )
    {
        float h = map(ro + rd*t);
        if( h<0.001 )
            return 0.0;
        float y = h*h/(2.0*ph);
        float d = sqrt(h*h-y*y);
        res = min( res, k*d/max(0.0,t-y) );
        ph = h;
        t += h;
    }
    return res;
}
float tri(in float x){return abs(fract(x)-.5);}

// fog & noise from Dave Hoskins: https://www.shadertoy.com/view/Xls3D2
vec3 tri3(in vec3 p){return vec3( tri(p.z+tri(p.y)), tri(p.z+tri(p.x)), tri(p.y+tri(p.x)));}
float Noise3d(in vec3 p)
{
    float z=1.4;
	float rz = 0.;
    vec3 bp = p;
	for (float i=0.; i<= 2.; i++ )
	{
        vec3 dg = tri3(bp);
        p += (dg);

        bp *= 2.;
		z *= 1.5;
		p *= 1.3;

        rz+= (tri(p.z+tri(p.x+tri(p.y))))/z;
        bp += 0.14;
	}
	return rz;
}

float fogmap(in vec3 p, in float d)
{
    float h = p.y;
    p.xz -= tt*7.+sin(p.z*.3)*3.;
    p.y -= tt*.5;
    float at = 0.05;

    return (max(Noise3d(p*.008+.1)-.1,0.0)*Noise3d(p*.1))*at;
}

// why not put the raymarcher in a separate function (;
vec3 raymarch(vec3 ro, vec3 rd, float steps, inout float drift) {

    float mat = 0.,
          t   = 0.,
          d   = 0.;
    drift = 0.;
    vec3 p = ro;
    for(float i=.0; i<steps; i++) {

        d = map(p);
        mat = g_mat;  // save global material

        if(abs(d) < 0.0001 || t > 100.) break;
        drift +=  fogmap(p, d);
        t += d;
        p += rd*d;
    }
    drift = min(drift, 1.0);
    return vec3(t, mat, t);
}

// from iq code
float softshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
	float res = 1.0;
    float t = mint;
    for( int i=0; i<1; i++ )
    {
		float h = map( ro + rd*t );
        res = min( res, 8.0*h/t );
        t += h*.25;
        if( h<0.001 || t>tmax ) break;
    }
    return clamp( res, 0., 1. );
}

float calcAO(vec3 p, vec3 n)
{
	float sca = 2.0, occ = 0.0;
    for( int i=0; i<5; i++ ){

        float hr = 0.01 + float(i)*0.5/4.0;        
        float dd = map(n * hr + p);
        occ += (hr - dd)*sca;
        sca *= 0.7;
    }
    return clamp( 1.0 - occ, 0.0, 1.0 );    
}



vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {

    // camera system
    vec3 f = normalize(l - p),  // forward vector
         r = normalize(cross(vec3(0, 1, 0), f)), // right vector
         u = cross(f, r), // up vector
         c = p + f * z, // center of virtual screen
         i = c + uv.x * r + uv.y * u, // intersection with screen
         rd = normalize(i - p);  // ray direction

    return rd;

}

// Shane awesome work below
// Tri-Planar blending function. Based on an old Nvidia tutorial.
vec3 tex3D( sampler2D tex, in vec3 p, in vec3 n ){

    n = max((abs(n) - 0.2)*7., 0.001); // n = max(abs(n), 0.001), etc.
    n /= (n.x + n.y + n.z ); 
	return (texture(tex, p.yz)*n.x + texture(tex, p.zx)*n.y + texture(tex, p.xy)*n.z).xyz;
}



vec3 iriTex( sampler2D tex, in vec3 p, in vec3 n ) {
    vec3 texCol = tex3D(iChannel1, p, n).rgb;
    texCol = texCol;
    mat3 tfm;
    tfm[0] = vec3(texCol.r,0.0,0);
    tfm[1] = vec3(0.0,texCol.b,0);
    tfm[2] = vec3(0,0,1.);    
    n = max((abs(n) - 0.2)*7., 0.001); // n = max(abs(n), 0.001), etc.
    n /= (n.x + n.y + n.z );

    float t = 0.05*tt;
    float s = .5;
    vec2 muvXY = (vec3(p.xy*s,1.0)*tfm).xy - t;
    vec2 muvXZ = (vec3(p.xz*s,1.0)*tfm).xy - t;
    vec2 muvYZ = (vec3(p.yz*s,1.0)*tfm).xy - t;

	return (texture(iChannel2, muvYZ*.1)*n.x + texture(iChannel2, muvXZ*.1)*n.y + texture(iChannel2, muvXY*.1)*n.z).xyz;    
}

// Texture bump mapping. Four tri-planar lookups, or 12 texture lookups in total. I tried to 
// make it as concise as possible. Whether that translates to speed, or not, I couldn't say.
vec3 texBump( sampler2D tx, in vec3 p, in vec3 n, float bf){

    const vec2 e = vec2(0.002, 0);

    // Three gradient vectors rolled into a matrix, constructed with offset greyscale texture values.    
    mat3 m = mat3( tex3D(tx, p - e.xyy, n), tex3D(tx, p - e.yxy, n), tex3D(tx, p - e.yyx, n));

    vec3 coeffs = vec3(0.299*SIN(tt), 0.587, 0.114*SIN(.7*tt));
    vec3 g = coeffs*m; // Converting to greyscale.
    g = (g - dot(tex3D(tx,  p , n), coeffs) )/e.x; g -= n*dot(n, g);

    return normalize( n + g*bf ); // Bumped normal. "bf" - bump factor.

}

vec3 doShade(vec3 p, vec3 n, vec3 rd, vec3 lp, vec3 lp2, float mat, vec3 rm, vec2 uv, float fog) {
    vec3 al = vec3(1);
    vec3 col = vec3(0);

    // background color
    vec3 c1 = vec3(0.106,0.255,0.275);
    vec3 c2 = vec3(0.165,0.051,0.286);

    float night = SIN(.2*tt+.25*PI);;
    vec3 bgCol = mix(vec3(0.620,0.769,0.878),vec3(0.490,0.529,0.729), uv.y+.2);
    vec3 bg = mix(.02, 0.23,night )*mix(bgCol, vec3(0.), length(uv*.6)*.5); // background

    //bg = mix(vec3(0.984,0.875,0.635)*.2, bg, length(uv*3.)*.3*(night));
    // light color
    vec3 lc1 = vec3(0.690,0.839,0.910);
    vec3 lc2 = vec3(0.933,0.871,0.788);


    if(mat == 0.) {
        n = texBump(iChannel1,p*1.4,n,.04);
    } else if(mat == 1.) {
        n = texBump(iChannel1,p*.6,n,.01);
        n = texBump(iChannel1,p*1.9,n,.08);
    }


    if(rm.x < 50.) {


        vec3 l = normalize(lp-p);
        vec3 l2 = normalize(lp2-p);

        float dif = max(dot(n, l), .0);
        float dif2 = max(dot(n, l2), .0);
        float spe = pow(max(dot(reflect(-rd, n), -l), .0),40.);

        float shd=softshadow( p, l, 0.1, 10. );

        float sss = smoothstep(0., 1., map(p + l * .3)) / .4;
        float sss2 = smoothstep(0., 1., map(p + l2 * .3)) / .4;


        vec3 n2 = n;
        n2.xy += noise(p.xy) * .5 - .025;
        n2 = normalize(n2);
        float height = atan(n2.y, n2.x);

        vec3 iri = spectral_zucconi6(height*1.11)*smoothstep(.8, .2, abs(n2.z))-.02;

        col += .5*((dif+.8*sss)*lc1 + (.6*sss2+dif2)*lc2*.8);

        if(mat == 1.) {
            al = vec3(0.271,0.349,0.408)*1.5;
        }

        col *= al;

        col += .05*iri;

        float ao = calcAO(p, n);

        col *= mix(col, col*ao, .8);

        rd = reflect(rd, n);

        vec3 refl = texture(iChannel0, rd).rgb;
        refl = mix(refl, refl.rrr, .5);
        refl = invGamma(refl);

        col = mix(col, refl, .08);

        if(mat == 0.) {
            col = mix(col, col*1.4, night);
        }

        float t = rm.z;

        float r = smoothNoise21(p.xz*1.+tt);

       // float fog = 1.-exp(-t*t*t*0.0001);

        //col = mix(col, bg, fog);

        col = mix(col, col*shd, .4);

    } else {
        col = bg;
        //rd.xz *= rot(.1*tt);
        col += (1.-night)*.05*stars(rd.yz*1.8);
    } 
    return col;

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   	vec2 uv = (fragCoord - .5*iResolution.xy)/iResolution.y;

    tt = iTime + 20.;
    float zoom = 9.;
    vec3  lp = vec3(5, 10., -5.),
          lp2 = vec3(-5., -4., 10);

    //uv = uv.yx;
    vec3 col;


    ro = vec3(0, 0, 0.);
    float camY = -2.+2.*SIN(.2*tt);;
    ro.y += camY;
    cam(ro);
    cam(lp);
    cam(lp2);
    vec3 lookat = vec3(0, 0, 0), p;

    vec3 rd = getRayDir(uv, ro, lookat, 1.);

    //rd.z -= 2.*SIN(1.*tt);

  //  cam(rd);

    float mat = 0.,
          t   = 0.,
          d   = 0.;


    vec2 e = vec2(0.0035, -0.0035);

    float alpha = 0.;
    float fog = 0.0;

    // currently only one pass
    for(float i = 0.; i < 1.; i++) {
        float steps = i > 0. ? 50. : 300.;
        vec3 rm = raymarch(ro, rd, steps, fog);

        float glow = g_glow;
        mat = rm.y;

        vec3 p = ro + rm.x*rd;

        p = g_p;
        float h = g_h;

        vec3 n = normalize( e.xyy*map(p+e.xyy) + e.yyx*map(p+e.yyx) +
                            e.yxy*map(p+e.yxy) + e.xxx*map(p+e.xxx));

        col = doShade(p, n, rd, lp, lp2, mat, rm, uv, fog);

        //col = vec3(h*5.);
        if(mat == 2. && rm.x < 20.) {
            rd = reflect(rd, n);

           // ro.y += camY;
            ro = p;


            ro += 0.01*n,
            rm = raymarch(ro, rd, 500., fog);

            mat = rm.y;
            p = g_p;



            n = normalize( e.xyy*map(p+e.xyy) + e.yyx*map(p+e.yyx) +
                                e.yxy*map(p+e.yxy) + e.xxx*map(p+e.xxx));

            vec3 refl = .7*doShade(p, n, rd, lp, lp2, mat, rm, uv, fog);
            col = mix(col, refl, .8);
           // if(dot(refl, .33*vec3(1))  < 0.5)
                //col = mix(col, refl, .9);
        }

        col = mix(col, vec3(0.639,0.827,1.000)*.2, fog);


    }


    col *= mix(.2, 1., (1.5-pow(dot(uv, uv), .5))); // vignette

    col = mix(col, vec3(0.600,0.773,1.000)*dot(col, vec3(1, 1, 1)*.3), .4*length(uv));

    // tone mapping
    col = pow(col*1.4, vec3(1.3))*1.2;

    col = pow(col, vec3(1. / 1.4)) * 1.9;
    col = pow(col, vec3(2.)) * 2.8;


    col = gamma(col); // gamma


    fragColor = vec4(col, alpha);
}

#define PI 3.141592

// glitch static noise
vec2 sfx(float time)
{
    //time = mod(time, 60.);
    float tt = mod(time, PI);
    float vol = smoothstep(.34, .4, tt/PI)-smoothstep(.8, .9, tt/PI);
    vec2 pan = vec2(sin(4.*time), cos(4.*time))*.2+.5;
    float pitch = sin(220.4*tt/48.);
    float tone = fract(sin(PI*2.*440.0*tt/9.)*500.);
    tone = sin(PI*2.*440.0/8.*tt);
    //tone = fract(sin(PI*2.*440.0*tt/9.)*500.);
    tone += .5*fract(sin(PI*2.*440.0*tt/9.)*mix(500., 400., tt/PI));

    return vec2( tone)*vol*pan;
}

